/**
 * One row in the Git-tab Stashes view. `ref_name` is git's reflog selector
(`stash@{0}`); `sha` is the full commit SHA of the stash snapshot, so the
frontend opens the stash diff through the existing `commit_sha` path
(`git diff <sha>^..<sha>`, the range summarized below). `message` is the
stash description (git's reflog subject), `date` its ISO-8601 creation
time, and the `files_changed` / `additions` / `deletions` numstat matches
the diff a row expands to.
 */
export interface StashEntry {
  additions: number;
  date: string;
  deletions: number;
  files_changed: number;
  message: string;
  ref_name: string;
  sha: string;
}

/**
 * Stable selector for apply, pop, and drop. The backend must re-resolve
`ref_name` and reject the mutation if it no longer matches `expected_sha`.
 */
export interface StashMutationBody {
  expected_sha: string;
  feature_id: number;
  ref_name: string;
}

export type StashPushBodyMessage = string | null;

/**
 * Create a stash. A non-blank message is passed to Git; `None` or blank input
uses Git's default stash description. Untracked files are opt-in and ignored
files are never included.
 */
export interface StashPushBody {
  feature_id: number;
  include_untracked?: boolean;
  message?: StashPushBodyMessage;
}

